package knowledge

import (
	"fmt"
	"sort"
	"strings"
)

// RenderIndex is kb/index.md as scripts/kb.py index generates it from the pages' front matter: byte for byte, so the
// shipped index cannot drift from the pages (AI-52). The assistant's own, reader-filtered index is built from the same
// rows by Entries.
func RenderIndex(pages []Page) string {
	var good []Page
	drafts := 0
	for _, p := range pages {
		if !p.front.empty() && p.Key != "" {
			good = append(good, p)
			if p.Status == "draft" {
				drafts++
			}
		}
	}
	lines := []string{
		"# Knowledge-base index",
		"",
		"Generated by `scripts/kb.py index` from page front matter; do not edit by hand. " +
			"Schema: `" + Schema + "` ([schema.md](schema.md)). The assistant reads this index first " +
			"(PRD-001 AI-51); at runtime it is filtered to what the reader may see (AI-54).",
		"",
		fmt.Sprintf("%d pages · %d draft", len(good), drafts),
	}
	for _, t := range Types {
		var group []Page
		for _, p := range good {
			if p.Type == t {
				group = append(group, p)
			}
		}
		if len(group) == 0 {
			continue
		}
		sort.SliceStable(group, func(i, j int) bool { return group[i].Key < group[j].Key })
		lines = append(lines, "", "## "+t, "", "| Key | Summary | Status | Data class |", "|---|---|---|---|")
		for _, p := range group {
			link := strings.TrimPrefix(p.File, "kb/")
			summary := strings.ReplaceAll(p.Summary, "|", `\|`)
			lines = append(lines, fmt.Sprintf("| [%s](%s) | %s | %s | %s |", p.Key, link, summary, p.Status, p.DataClass))
		}
	}
	return strings.Join(lines, "\n") + "\n"
}

// Entry is one row of an index the assistant reads: what a page is, in a line.
type Entry struct {
	Key       string
	Type      string
	Title     string
	Summary   string
	Status    string
	DataClass string
}

// Entries are the rows of the pages' index, by type then key, as the generated index lists them.
func Entries(pages []Page) []Entry {
	var out []Entry
	for _, t := range Types {
		var group []Page
		for _, p := range pages {
			if p.Type == t && p.Key != "" {
				group = append(group, p)
			}
		}
		sort.SliceStable(group, func(i, j int) bool { return group[i].Key < group[j].Key })
		for _, p := range group {
			out = append(out, Entry{Key: p.Key, Type: p.Type, Title: p.Title, Summary: p.Summary, Status: p.Status, DataClass: p.DataClass})
		}
	}
	return out
}
